package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import android.database.sqlite.SQLiteDatabase;import org.json.*;

/** Creation uses the production document editor and native image storage, without model calls. */
public final class CreationUiTest extends DocumentEditorTest {
 final String prefix="qa-creation-ui-",id=prefix+"article",draftId=prefix+"draft";String original="";
 String originals(JSONArray all)throws Exception{JSONArray keep=new JSONArray();for(int i=0;i<all.length();i++)if(!all.getJSONObject(i).getString("id").startsWith(prefix))keep.put(all.getJSONObject(i));return keep.toString();}
 void offline()throws Exception{until("typeof document.querySelector('[data-page=records]').onclick==='function'");h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");}
 void clean()throws Exception{for(String key:new String[]{id,draftId}){h.call("deleteRecord",new JSONObject().put("id",key));h.call("clearDocumentDraft",new JSONObject().put("id",key));}}
 void uid(String value)throws Exception{h.js("(()=>{const f=LifeDomain.uid;LifeDomain.uid=()=>{LifeDomain.uid=f;return "+JSONObject.quote(value)+";};})()");}
 void saveRead()throws Exception{click("#doc-save");if(h.js("document.querySelector('#confirm-dialog').open").equals("true"))click("#confirm-ok");until("!document.querySelector('#doc-save').disabled&&document.querySelector('#doc-mode').textContent==='编辑'&&!document.querySelector('#doc-read').hidden");}
 void fits(String label)throws Exception{
  check(h.js("document.documentElement.scrollWidth<=innerWidth+1").equals("true"),label+": no horizontal overflow");
  check(h.js("[...document.querySelectorAll('.creation-library button,.creation-library input')].every(b=>{const r=b.getBoundingClientRect();return !r.width||r.height>=47&&r.left>=-1&&r.right<=innerWidth+1})").equals("true"),label+": controls remain visible and touchable");
 }
 void checks()throws Exception{
  h=new MainHost(this);h.open();offline();clean();original=originals(records());
  click("[data-page=records]");click("[data-record-tab=creation]");until("!!document.querySelector('#creation-new')");check(h.js("document.querySelectorAll('.bottom-nav button').length===4&&document.querySelector('[data-record-tab=creation]').textContent.includes('创作')").equals("true"),"Creation is a record category, keeping four bottom destinations");
  uid(id);click("#creation-new");until("!!document.querySelector('#doc-body')");check(h.js("document.querySelector('.document-kind').textContent.includes('创作')&&!!document.querySelector('#doc-image')&&!!document.querySelector('#doc-format')").equals("true"),"New creation reuses image and formatting editor controls");
  input("QA图文创作：让记录成为可发布的故事","## 从一次学习开始\n\n用亲身经历组织图文内容，讲清楚观点和例子。");
  JSONObject image=(JSONObject)h.call("storeRecordImage",new JSONObject().put("data",image()).put("name","QA创作插图.png"));h.js("window.nativeEvent('recordImage',"+image.toString()+")");until("!!document.querySelector('#doc-body img')&&document.querySelector('#doc-body img').naturalWidth===320");
  click("#doc-info");h.js("document.querySelector('[data-meta=creatorPlatform]').value='公众号';document.querySelector('[data-meta=creationStatus]').value='ready'");check(h.js("!document.querySelector('#doc-meta [data-meta=durationMinutes]')").equals("true"),"Creation metadata contains platform and status without learning duration");click("#doc-meta-done");saveRead();
  JSONObject r=record(id);check(r.getString("type").equals("creation")&&r.getDouble("durationMinutes")==0&&r.getString("creatorPlatform").equals("公众号")&&r.getString("creationStatus").equals("ready"),"Committed creation stays separate from learning, work and essays");check(r.getJSONArray("images").length()==1&&r.getString("note").contains("zhishi-media:")&&r.getString("note").contains("亲身经历"),"Source text and inserted image persist together");
  until("!!document.querySelector('#doc-flow img')&&document.querySelector('#doc-flow img').naturalWidth===320");click("#doc-flow img");until("!!document.querySelector('#doc-image-viewer')");check(true,"Creation reader images open the existing large preview");click("#doc-image-close");close();
  check(h.js("document.querySelector('[data-record="+id+"]').innerText.includes('待发布')&&document.querySelector('[data-record="+id+"]').innerText.includes('1 张图片')").equals("true"),"Library shows publication state and media count");
  click("[data-creation-status=ready]");check(h.js("!!document.querySelector('[data-record="+id+"]')").equals("true"),"Ready filter includes the saved manuscript");click("[data-creation-status=published]");check(h.js("!document.querySelector('[data-record="+id+"]')").equals("true"),"Published filter excludes manuscripts not marked published");click("[data-creation-status='']");
  h.js("document.querySelector('#creation-search').value='亲身经历';document.querySelector('#creation-search').dispatchEvent(new Event('input'))");check(h.js("!!document.querySelector('[data-record="+id+"]')").equals("true"),"Creation search covers full stored content");fits("portrait creation library");h.screenshot("creation-library.png");runOnMainSync(()->h.web.getSettings().setTextZoom(200));Thread.sleep(250);fits("large text creation library");h.screenshot("creation-library-large.png");runOnMainSync(()->h.web.getSettings().setTextZoom(100));
  click("[data-record="+id+"]");until("!!document.querySelector('#doc-flow')");click("#doc-mode");click("#doc-info");h.js("document.querySelector('[data-meta=creationStatus]').value='published';document.querySelector('[data-meta=publishedUrl]').value='https://example.com/qa-creation'");click("#doc-meta-done");saveRead();close();r=record(id);check(r.getString("creationStatus").equals("published")&&r.getJSONArray("images").length()==1&&r.getString("note").contains("亲身经历"),"Editing publication metadata preserves original text and media");
  uid(draftId);click("#creation-new");until("!!document.querySelector('#doc-body')");input("QA未完成创作稿","这一篇未完成的创作只保留在本机草稿。");close();JSONArray drafts=(JSONArray)h.call("getDocumentDraft",new JSONObject());boolean found=false;for(int i=0;i<drafts.length();i++)if(drafts.getJSONObject(i).getJSONObject("record").getString("id").equals(draftId))found=drafts.getJSONObject(i).getJSONObject("record").getString("type").equals("creation");check(found,"Uncommitted creation remains recoverable as a creation draft");check(originals(records()).equals(original),"Existing source records remain unchanged");
 }
 @Override public void onStart(){Bundle out=new Bundle();boolean ok=false;try{if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Disposable emulator required");checks();ok=true;out.putString("stream","PASS CreationUiTest: "+passed+" checks\n");}catch(Throwable error){out.putString("stream","FAIL CreationUiTest after "+passed+": "+android.util.Log.getStackTraceString(error));try{if(h!=null)h.screenshot("creation-failure.png");}catch(Exception ignored){}}finally{try{if(h!=null){runOnMainSync(()->h.web.getSettings().setTextZoom(100));clean();runOnMainSync(()->h.activity.finish());}}catch(Exception ignored){}}finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
